import { z } from "zod";

// Candidate Profile shape from profiles.json
export interface CandidateProfile {
  id: string;
  name: string;
  current_title: string;
  years_experience: number;
  location: string;
  current_company: string;
  current_company_type: "startup" | "scaleup" | "enterprise" | "agency";
  skills: string[];
  past_companies: {
    company: string;
    company_type: string;
    title: string;
    years: number;
  }[];
  education: string;
  summary: string;
}

// Objective Filters Schema generated by LLM
export const ObjectiveFiltersSchema = z.object({
  min_years_experience: z.number().default(0),
  max_years_experience: z.number().optional(),
  locations: z.array(z.string()).default([]),
  skills: z.array(z.string()).default([]),
  company_types: z.array(z.string()).default([]),
});

export type ObjectiveFilters = z.infer<typeof ObjectiveFiltersSchema>;

// Subjective Rubric Schema generated by LLM
export const FitRubricSchema = z.object({
  criteria: z.array(z.string()),
});

export type FitRubric = z.infer<typeof FitRubricSchema>;

// Scored Candidate Schema
export interface ScoredCandidate {
  profile: CandidateProfile;
  score: number;
  explanation: string;
}